CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, category TEXT NOT NULL, description TEXT NOT NULL, price_cents INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft', image TEXT NOT NULL DEFAULT '', features TEXT NOT NULL DEFAULT '[]', checkout_url TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS releases (id TEXT PRIMARY KEY, product_id TEXT NOT NULL, version TEXT NOT NULL, r2_key TEXT NOT NULL, file_name TEXT NOT NULL, file_size INTEGER NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 0, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, product_id TEXT NOT NULL, customer_email TEXT NOT NULL, amount_cents INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', provider_ref TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS licenses (id TEXT PRIMARY KEY, product_id TEXT NOT NULL, customer_email TEXT NOT NULL, license_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'active', download_count INTEGER NOT NULL DEFAULT 0, max_downloads INTEGER NOT NULL DEFAULT 5, expires_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
